	for i := 1; i <= n; i++ {
		for j := 1; j <= m; j++ {
			if a[i-1] == b[j-1] {
				dp[i][j] = dp[i-1][j-1] + 1
			} else {
				dp[i][j] = maxInt(dp[i-1][j], dp[i][j-1])
			}
		}
	}
	return dp
}

func rebuild(a, b string, dp [][]int) string {
	i, j := len(a), len(b)
	out := make([]byte, dp[i][j])
	k := len(out) - 1
	for i > 0 && j > 0 {
		if a[i-1] == b[j-1] {
			out[k] = a[i-1]
			k--
			i--
			j--
		} else if dp[i-1][j] >= dp[i][j-1] {
			i--
		} else {
			j--
		}
	}
	return string(out)
}

func main() {
	pairs := [][2]string{{"AGCAT", "GAC"}, {"GATTACA", "GCATGCT"}, {"AAAA", "TTTT"}}
	for _, p := range pairs {
		shared := rebuild(p[0], p[1], lcsTable(p[0], p[1]))
		if shared == "" {
			shared = "none"
		}
		fmt.Printf("%s and %s: %s\n", p[0], p[1], shared)
	}
}

