n, m := len(a), len(b)
dp := make([][]int, n+1)
for i := range dp {
	dp[i] = make([]int, m+1)
}
for i := 0; i <= n; i++ {
	dp[i][0] = i
}
for j := 0; j <= m; j++ {
	dp[0][j] = j
}
for i := 1; i <= n; i++ {
	for j := 1; j <= m; j++ {
		if a[i-1] == b[j-1] {
			dp[i][j] = dp[i-1][j-1]
		} else {
			dp[i][j] = 1 + minInt(dp[i-1][j], minInt(dp[i][j-1], dp[i-1][j-1]))
		}
	}
}
fmt.Println(dp[n][m]) // 3
```

`minInt` takes two values, so nest it for three. The 3 edits are: replace `k` with `s`, replace `e` with `i`, and insert `g`. It's the same table as the LCS, so it's O(n * m) time and space too.

